        JSONObject receipt=new JSONObject().put("request_id","qa_explicit_selection").put("selected",new JSONArray().put(choice)).put("selected_storage",selected).put("clear_storage",device.getJSONObject("storage")).put("selection_hash",PixelMcpWriteTools.hash(selected));String immutableReceipt=receipt.toString();RestoredBrowserReviewRules.validateSelection(backup,device,receipt);checks++;
